def run_program(args: argparse.Namespace, parser: argparse.ArgumentParser) -> int:
    if args.version:
        print('online-judge-tools {} (+ online-judge-api-client {})'.format(version.__version__, api_version.__version__))
        return 0
    logger.debug('args: %s', str(args))

    # print the version to use for user-supporting
    logger.info('online-judge-tools %s (+ online-judge-api-client %s)', version.__version__, api_version.__version__)

    # TODO: make functions for subcommand take a named tuple instead of the raw result of argparse. Using named tuples make code well-typed.
    if args.subcommand in ['download', 'd', 'dl']:
        if not subcommand_download.run(args):
            return 1
    elif args.subcommand in ['login', 'l']:
        if not subcommand_login.run(args):
            return 1
    elif args.subcommand in ['submit', 's']:
        if not subcommand_submit.run(args):
            return 1
    elif args.subcommand in ['test', 't']:
        if not subcommand_test.run(args):
            return 1
    elif args.subcommand in ['test-reactive', 't/r', 'test-interactive', 't/i']:
        if not subcommand_test_reactive.run(args):
            return 1
    elif args.subcommand in ['generate-output', 'g/o']:
        subcommand_generate_output.run(args)
    elif args.subcommand in ['generate-input', 'g/i']:
        subcommand_generate_input.run(args)
    else:
        parser.print_help(file=sys.stderr)
        return 1
    return 0

def __init__(self, datefmt: Optional[str] = None):
    fmt = '[%(levelname)s] %(message)s'
    super().__init__(fmt=fmt, datefmt=datefmt)

def __init__(self, *, rel_tol: float, abs_tol: float):
    if max(rel_tol, abs_tol) > 1:
        logger.warning('the tolerance is too large: relative = %s, absolute = %s', rel_tol, abs_tol)
    self.rel_tol = rel_tol
    self.abs_tol = abs_tol

def __init__(self, judge_command: str, *, is_silent: bool):
    self.judge_command = judge_command  # already quoted and joined command
    self.is_silent = is_silent

def format(self, record: logging.LogRecord) -> str:
    if record.levelno not in log_colors_level:
        return super().format(record)

    # detect the heading from the record
    heading = None
    message = record.getMessage()
    if not message and record.exc_info is None:
        heading = ''
    if heading is None:
        for key, value in log_colors_semantics.items():
            if message.upper().startswith(key + ':'):
                heading = value
                message = message[len(key + ':'):].lstrip()
                break
    if heading is None:
        heading = log_colors_level[record.levelno]

    # exception
    if record.exc_info is not None:
        message += '\n' + self.formatException(record.exc_info)

    # make a string
    if not heading:
        return message
    return heading + message

def run(args: argparse.Namespace) -> None:
    # list tests
    if not args.test:
        args.test = fmtutils.glob_with_format(args.directory, args.format)  # by default
    if args.ignore_backup:
        args.test = fmtutils.drop_backup_or_hidden_files(args.test)
    tests = fmtutils.construct_relationship_of_files(args.test, args.directory, args.format)

    # generate cases
    if args.jobs is None:
        for name, paths in sorted(tests.items()):
            generate_output_single_case_exists_ok(name, paths['in'], paths.get('out'), args=args)
    else:
        with concurrent.futures.ThreadPoolExecutor(max_workers=args.jobs) as executor:
            lock = threading.Lock()
            futures: List[concurrent.futures.Future] = []
            for name, paths in sorted(tests.items()):
                futures += [executor.submit(generate_output_single_case_exists_ok, name, paths['in'], paths.get('out'), lock=lock, args=args)]
            for future in futures:
                future.result()

def convert_sample_to_dict(sample: TestCase) -> Dict[str, str]:
    data: Dict[str, str] = {}
    data["name"] = sample.name
    data["input"] = sample.input_data.decode()
    if sample.output_data is not None:
        data["output"] = sample.output_data.decode()
    return data

def run(args: argparse.Namespace) -> bool:
    # prepare values
    problem = dispatch.problem_from_url(args.url)
    if problem is None:
        if dispatch.contest_from_url(args.url) is not None:
            logger.warning('You specified a URL for a contest instead of a problem. If you want to download for all problems of a contest at once, please try to use `oj-prepare` command of https://github.com/online-judge-tools/template-generator')
        logger.error('The URL "%s" is not supported', args.url)
        return False
    is_default_format = args.format is None and args.directory is None  # must be here since args.directory and args.format are overwritten
    if args.directory is None:
        args.directory = pathlib.Path('test')
    if args.format is None:
        args.format = '%b.%e'

    # get samples from the server
    with utils.new_session_with_our_user_agent(path=args.cookie) as sess:
        if isinstance(problem, AtCoderProblem) and args.system:
            if not args.dropbox_token:
                logger.info(utils.HINT + 'You need to give the access token. Please do the following:\n%s', textwrap.dedent("""
                        1. Open the following URL in your browser:
                            https://www.dropbox.com/oauth2/authorize?client_id=153gig8dqgk3ujg&response_type=code
                        2. Authorize the app and take the access code.
                        3. Run the following command with replacing the "${YOUR_ACCESS_CODE}":
                            $ curl https://api.dropbox.com/oauth2/token --user 153gig8dqgk3ujg:5l7o7lh73o8i9ux --data grant_type=authorization_code --data code=${YOUR_ACCESS_CODE}
                        4. Get the access token from the JSON. It is in the "access_token" field.
                        5. Use the access token. For example:
                            $ oj download """ + problem.get_url() + """ --system --dropbox-token=${YOUR_ACCESS_TOKEN}

                    (Please take care that the access code and the access token are CONFIDENTIAL information. DON'T SHARE with other people!)
                """))
                raise SampleParseError("--dropbox-token is not given")
            sess.headers['Authorization'] = 'Bearer {}'.format(args.dropbox_token)
        if args.yukicoder_token and isinstance(problem, YukicoderProblem):
            sess.headers['Authorization'] = 'Bearer {}'.format(args.yukicoder_token)
        try:
            if args.system:
                samples = problem.download_system_cases(session=sess)
            else:
                samples = problem.download_sample_cases(session=sess)
        except requests.exceptions.RequestException as e:
            logger.error('%s', e)
            logger.error(utils.HINT + 'You may need to login to use `$ oj download ...` during contest. Please run: $ oj login %s', problem.get_service().get_url())
            return False
        except SampleParseError as e:
            logger.error('%s', e)
            return False

    if not samples:
        logger.error("Sample not found")
        return False

    # append the history for submit subcommand
    if not args.dry_run and is_default_format:
        history = onlinejudge_command.download_history.DownloadHistory()
        if not list(args.directory.glob('*')):
            # reset the history to help users who use only one directory for many problems
            history.remove(directory=pathlib.Path.cwd())
        history.add(problem, directory=pathlib.Path.cwd())

    # prepare files to write
    def iterate_files_to_write(sample: TestCase, *, i: int) -> Iterator[Tuple[str, pathlib.Path, bytes]]:
        for ext in ['in', 'out']:
            data = getattr(sample, ext + 'put_data')
            if data is None:
                continue
            name = sample.name
            table = {}
            table['i'] = str(i + 1)
            table['e'] = ext
            table['n'] = name
            table['b'] = os.path.basename(name)
            table['d'] = os.path.dirname(name)
            path: pathlib.Path = args.directory / format_utils.percentformat(args.format, table)
            yield ext, path, data

    for i, sample in enumerate(samples):
        for _, path, _ in iterate_files_to_write(sample, i=i):
            if path.exists():
                logger.error('Failed to download since file already exists: %s', str(path))
                logger.info(utils.HINT + 'We recommend adding your own test cases to test/ directory, and using one directory per one problem. Please see also https://github.com/online-judge-tools/oj/blob/master/docs/getting-started.md#random-testing. If you wanted to keep using one directory per one contest, you can run like `$ rm -rf test/ && oj d https://...`.')
                return False

    # write samples to files
    for i, sample in enumerate(samples):
        logger.info('')
        logger.info('sample %d', i)
        for ext, path, data in iterate_files_to_write(sample, i=i):
            content = ''
            if not args.silent:
                content = '\n' + pretty_printers.make_pretty_large_file_content(data, limit=40, head=20, tail=10)
            logger.info('%sput: %s%s', ext, sample.name, content)
            if not args.dry_run:
                path.parent.mkdir(parents=True, exist_ok=True)
                with path.open('wb') as fh:
                    fh.write(data)
                logger.info(utils.SUCCESS + 'saved to: %s', path)

    if args.log_file:
        with args.log_file.open(mode='w') as fhs:
            json.dump(list(map(convert_sample_to_dict, samples)), fhs)

    return True

def _optimize_tokens(tokens: List[_PrettyToken]) -> List[_PrettyToken]:
    optimized: List[_PrettyToken] = []
    for token in tokens:
        if optimized and optimized[-1].type == token.type:
            optimized[-1] = _PrettyToken(token.type, optimized[-1].value + token.value)
        else:
            optimized.append(token)
    return optimized

def _skip_whitespaces(i: int, s: str) -> Tuple[int, List[_PrettyToken]]:
    tokens = []
    while i < len(s) and s[i] in ' \t\r\n':
        if s[i] in ' \t':
            typ = _PrettyTokenType.WHITESPACE
        else:
            typ = _PrettyTokenType.NEWLINE
        tokens.append(_PrettyToken(typ, s[i]))
        i += 1
    return i, _optimize_tokens(tokens)

def _tokenize_str(s: str) -> List[_PrettyToken]:
    tokens = []
    l = 0
    while l < len(s):
        r = l + 1
        while r < len(s) and (s[l] in ' \t') == (s[r] in ' \t'):
            r += 1
        if s[l] in ' \t':
            typ = _PrettyTokenType.WHITESPACE
        else:
            typ = _PrettyTokenType.BODY
        tokens.append(_PrettyToken(typ, s[l:r]))
        l = r
    return tokens

def _tokenize_line(line: str) -> List[_PrettyToken]:
    body = line.rstrip()
    newline = line[len(body):]
    tokens = []

    # add the body of line
    if body:
        tokens += _tokenize_str(body)

    # add newlines
    if newline:
        if newline in ('\n', '\r\n'):
            tokens.append(_PrettyToken(_PrettyTokenType.NEWLINE, newline))
        else:
            whitespace = newline.rstrip('\n')
            newline = newline[len(whitespace):]
            if whitespace:
                tokens.append(_PrettyToken(_PrettyTokenType.WHITESPACE, whitespace))
            tokens.append(_PrettyToken(_PrettyTokenType.HINT, '(trailing whitespace)'))
            if newline:
                tokens.append(_PrettyToken(_PrettyTokenType.NEWLINE, newline))

    return tokens

def _warn_if_empty(tokens: List[_PrettyToken]) -> List[_PrettyToken]:
    if not tokens:
        return [_PrettyToken(_PrettyTokenType.HINT, '(empty)')]
    if tokens[-1][0] == _PrettyTokenType.BODY:
        tokens.append(_PrettyToken(_PrettyTokenType.HINT, '(no trailing newline)'))
    if all(token.type == _PrettyTokenType.NEWLINE for token in tokens):
        tokens.append(_PrettyToken(_PrettyTokenType.HINT, '(only newline)'))
    return tokens

def _tokenize_large_file_content(*, content: bytes, limit: int, head: int, tail: int, char_in_line: int) -> List[_PrettyToken]:
    """`_tokenize_large_file_content` constructs the intermediate representations. They have no color infomation.
    """

    assert head + tail < limit

    def candidate_do_nothing(text: str) -> List[_PrettyToken]:
        tokens = []
        for line in text.splitlines(keepends=True):
            tokens += _tokenize_line(line)
        return tokens

    def candidate_line_based(text: str) -> List[_PrettyToken]:
        lines = text.splitlines(keepends=True)
        if len(lines) < limit:
            return candidate_do_nothing(text)

        tokens = []
        for line in lines[:head]:
            tokens += _tokenize_line(line)
        tokens.append(_PrettyToken(_PrettyTokenType.HINT, '... ({} lines) ...\n'.format(len(lines[head:-tail]))))
        for line in lines[-tail:]:
            tokens += _tokenize_line(line)
        return tokens

    def candidate_char_based(text: str) -> List[_PrettyToken]:
        if len(text) < char_in_line * limit:
            return candidate_do_nothing(text)

        l = len(text[:char_in_line * head].rstrip())
        r = len(text) - char_in_line * tail
        tokens = []
        for line in text[:l].splitlines(keepends=True):
            tokens += _tokenize_line(line)
        tokens.append(_PrettyToken(_PrettyTokenType.HINT, '... ({} chars) ...'.format(r - l)))
        for line in text[r:].splitlines(keepends=True):
            tokens += _tokenize_line(line)
        return tokens

    def count_size(tokens: Iterable[_PrettyToken]) -> int:
        size = 0
        for _, s in tokens:
            size += len(s)
        return size

    # Choose the shortest one from the three candidates.
    tokens, text = _decode_with_recovery(content)
    if text:
        candidates: List[List[_PrettyToken]] = [
            candidate_do_nothing(text),
            candidate_line_based(text),
            candidate_char_based(text),
        ]
        tokens.extend(min(candidates, key=count_size))
    tokens = _warn_if_empty(tokens)
    return tokens

def _tokenize_file_content_without_snipping(content: bytes) -> List[_PrettyToken]:
    tokens, text = _decode_with_recovery(content)
    for line in text.splitlines(keepends=True):
        tokens += _tokenize_line(line)
    tokens = _warn_if_empty(tokens)
    return tokens

def _tokenize_str_with_highlight(s: str, *, is_right: bool) -> List[_PrettyToken]:
    tokens: List[_PrettyToken] = []
    for token in _tokenize_str(s):
        if token.type == _PrettyTokenType.BODY:
            typ = _PrettyTokenType.BODY_HIGHLIGHT_RIGHT if is_right else _PrettyTokenType.BODY_HIGHLIGHT_LEFT
            tokens.append(_PrettyToken(typ, token.value))
        else:
            tokens.append(token)
    return tokens

def _tokenize_line_with_highlight(line: str, *, is_right: bool) -> List[_PrettyToken]:
    tokens: List[_PrettyToken] = []
    for token in _tokenize_line(line):
        if token.type == _PrettyTokenType.BODY:
            typ = _PrettyTokenType.BODY_HIGHLIGHT_RIGHT if is_right else _PrettyTokenType.BODY_HIGHLIGHT_LEFT
            tokens.append(_PrettyToken(typ, token.value))
        else:
            tokens.append(token)
    return tokens

def _len_of_tokens(tokens: List[_PrettyToken]) -> int:
    result = 0
    for token in tokens:
        if token.type in (_PrettyTokenType.WHITESPACE, _PrettyTokenType.NEWLINE):
            result += len(_replace_whitespace(token.value).replace('\n', ''))
        else:
            result += len(token.value)
    return result

def _tokens_from_line_diff_ops(ops: List[_MergedDiffOp], *, char_in_line: int) -> List[_PrettyToken]:
    if not ops:
        return [_PrettyToken(_PrettyTokenType.HINT, '(no diff)')]

    left_width = char_in_line // 2

    # calculate the widths of lineno
    max_left_linno = 0
    max_right_linno = 0
    for op in ops:
        if op.left_lineno is not None:
            max_left_linno = op.left_lineno
        if op.right_lineno is not None:
            max_right_linno = op.right_lineno
    left_lineno_width = len(str(max_left_linno + 1))
    right_lineno_width = len(str(max_right_linno + 1))
    assert left_lineno_width + 2 + 10 <= left_width
    assert right_lineno_width + 2 + 10

    tokens = []
    tokens.append(_PrettyToken(_PrettyTokenType.OTHERS, 'output:'.ljust(left_width) + 'expected:'))
    tokens.append(_PrettyToken(_PrettyTokenType.NEWLINE, '\n'))
    for op in ops:
        if op == _MergedDiffOpDots:
            tokens.append(_PrettyToken(_PrettyTokenType.OTHERS, '...'.ljust(left_width) + '...'))
            tokens.append(_PrettyToken(_PrettyTokenType.NEWLINE, '\n'))
            continue
        left_exists = False
        if op.left_lineno is not None:
            tokens.append(_PrettyToken(_PrettyTokenType.LINENO, str(op.left_lineno + 1).rjust(left_lineno_width)))
            tokens.append(_PrettyToken(_PrettyTokenType.OTHERS, '| '))
            tokens.extend([_PrettyToken(token.type, token.value.replace('\n', '')) for token in op.left])
            padding = left_width - (left_lineno_width + 2 + _len_of_tokens(op.left))
            if padding >= 0:
                tokens.append(_PrettyToken(_PrettyTokenType.OTHERS, ' ' * padding))
                left_exists = True
            else:
                tokens.append(_PrettyToken(_PrettyTokenType.OTHERS, '\n'))
        if op.right_lineno is not None:
            if not left_exists:
                tokens.append(_PrettyToken(_PrettyTokenType.OTHERS, ' ' * left_width))
            tokens.append(_PrettyToken(_PrettyTokenType.LINENO, str(op.right_lineno + 1).rjust(right_lineno_width)))
            tokens.append(_PrettyToken(_PrettyTokenType.OTHERS, '| '))
            tokens.extend(op.right)
        else:
            if left_exists:
                tokens.append(_PrettyToken(_PrettyTokenType.OTHERS, '\n'))
    return tokens

def candidate_do_nothing(text: str) -> List[_PrettyToken]:
    tokens = []
    for line in text.splitlines(keepends=True):
        tokens += _tokenize_line(line)
    return tokens

def candidate_line_based(text: str) -> List[_PrettyToken]:
    lines = text.splitlines(keepends=True)
    if len(lines) < limit:
        return candidate_do_nothing(text)

    tokens = []
    for line in lines[:head]:
        tokens += _tokenize_line(line)
    tokens.append(_PrettyToken(_PrettyTokenType.HINT, '... ({} lines) ...\n'.format(len(lines[head:-tail]))))
    for line in lines[-tail:]:
        tokens += _tokenize_line(line)
    return tokens

def candidate_char_based(text: str) -> List[_PrettyToken]:
    if len(text) < char_in_line * limit:
        return candidate_do_nothing(text)

    l = len(text[:char_in_line * head].rstrip())
    r = len(text) - char_in_line * tail
    tokens = []
    for line in text[:l].splitlines(keepends=True):
        tokens += _tokenize_line(line)
    tokens.append(_PrettyToken(_PrettyTokenType.HINT, '... ({} chars) ...'.format(r - l)))
    for line in text[r:].splitlines(keepends=True):
        tokens += _tokenize_line(line)
    return tokens

def count_size(tokens: Iterable[_PrettyToken]) -> int:
    size = 0
    for _, s in tokens:
        size += len(s)
    return size

def _decode_with_recovery(content: bytes) -> Tuple[List[_PrettyToken], str]:
    tokens = []
    try:
        text = content.decode()
    except UnicodeDecodeError as e:
        tokens.append(_PrettyToken(_PrettyTokenType.HINT, str(e)))
        text = content.decode(errors='replace')
    return tokens, text

def _get_terminal_size() -> int:
    char_in_line, _ = shutil.get_terminal_size()
    return max(char_in_line, 40)  # shutil.get_terminal_size() may return too small values (e.g. (0, 0) on Circle CI) successfully (i.e. fallback is not used). see https://github.com/kmyk/online-judge-tools/pull/611

def make_pretty_large_file_content(content: bytes, limit: int, head: int, tail: int) -> str:
    char_in_line = _get_terminal_size()
    tokens = _tokenize_large_file_content(content=content, limit=limit, head=head, tail=tail, char_in_line=char_in_line)
    return _render_tokens(tokens=tokens)

def make_pretty_all(content: bytes) -> str:
    tokens = _tokenize_file_content_without_snipping(content=content)
    return _render_tokens(tokens=tokens)

def make_pretty_diff(output_bytes: bytes, *, expected: str, compare_mode: CompareMode, limit: int) -> str:
    tokens, output = _decode_with_recovery(output_bytes)
    char_in_line = _get_terminal_size()
    tokens += _tokenize_pretty_diff(output, expected=expected, compare_mode=compare_mode, char_in_line=char_in_line, limit=limit)
    return _render_tokens(tokens=tokens)

def _make_diff_between_line_and_line_by_difflib(a: str, b: str) -> Tuple[List[_PrettyToken], List[_PrettyToken]]:
    tokens_a = []
    tokens_b = []

    # https://docs.python.org/ja/3/library/difflib.html#difflib.SequenceMatcher.get_opcodes
    matcher: difflib.SequenceMatcher = difflib.SequenceMatcher()
    matcher.set_seqs(a.rstrip('\n'), b.rstrip('\n'))
    for (tag, l_a, r_a, l_b, r_b) in matcher.get_opcodes():
        if tag == 'replace':
            tokens_a.extend(_tokenize_str_with_highlight(a[l_a:r_a], is_right=False))
            tokens_b.extend(_tokenize_str_with_highlight(b[l_b:r_b], is_right=True))
        elif tag == 'delete':
            assert l_b == r_b
            tokens_a.extend(_tokenize_str_with_highlight(a[l_a:r_a], is_right=False))
        elif tag == 'insert':
            assert l_a == r_a
            tokens_b.extend(_tokenize_str_with_highlight(b[l_b:r_b], is_right=True))
        elif tag == 'equal':
            tokens_a.extend(_tokenize_str(a[l_a:r_a]))
            tokens_b.extend(_tokenize_str(b[l_b:r_b]))
        else:
            assert False

    if len(a.rstrip('\n')) < len(a):
        tokens_a.append(_PrettyToken(_PrettyTokenType.NEWLINE, a[len(a.rstrip('\n')):]))
    if len(b.rstrip('\n')) < len(b):
        tokens_b.append(_PrettyToken(_PrettyTokenType.NEWLINE, b[len(b.rstrip('\n')):]))
    tokens_a = _optimize_tokens(tokens_a)
    tokens_b = _optimize_tokens(tokens_b)
    return tokens_a, tokens_b

def _make_diff_between_line_and_line(a: str, b: str) -> Tuple[List[_PrettyToken], List[_PrettyToken]]:
    if len(a.strip().split()) == len(b.strip().split()):
        return _make_diff_between_line_and_line_by_comparing_word_by_word(a, b)
    else:
        return _make_diff_between_line_and_line_by_difflib(a, b)

def _make_diff_between_file_and_file(a: str, b: str, *, compare_mode: CompareMode) -> List[_LineDiffOp]:
    assert compare_mode != CompareMode.IGNORE_SPACES_AND_NEWLINES
    if len(a.rstrip().splitlines()) == len(b.rstrip().splitlines()):
        return _make_diff_between_file_and_file_by_comparing_line_by_line(a, b, compare_mode=compare_mode)
    else:
        if compare_mode in (CompareMode.IGNORE_SPACES, CompareMode.IGNORE_SPACES_AND_NEWLINES):
            logger.warning('ignoring --compare-mode=%s and using --compare-mode=%s (default) instead for generating diff...', str(compare_mode), str(CompareMode.CRLF_INSENSITIVE_EXACT_MATCH))
            compare_mode = CompareMode.CRLF_INSENSITIVE_EXACT_MATCH
        if compare_mode == CompareMode.CRLF_INSENSITIVE_EXACT_MATCH:
            if '\r' in a or '\r' in b:
                logger.warning("carriage return '\\r' is removed from diff")
                a = a.replace('\r\n', '\n')
                b = b.replace('\r\n', '\n')
        return _make_diff_between_file_and_file_by_difflib(a, b)

def _add_lines_around_diff_lines(a: str, b: str, *, ops: List[_LineDiffOp], size: int) -> List[_MergedDiffOp]:
    result: List[_MergedDiffOp] = []
    unused: List[_MergedDiffOp] = []
    use = 0
    for op in _reconstruct_entire_diff(a, b, ops=ops):
        if op.has_diff:
            result += unused[-size:]
            unused = []
            result.append(op)
            use = size
        else:
            if use:
                result.append(op)
                use -= 1
            else:
                unused.append(op)
    return result

def _add_dots_between_gaps(a: str, b: str, *, ops: List[_MergedDiffOp]) -> List[_MergedDiffOp]:
    result: List[_MergedDiffOp] = []

    # body
    for op in ops:
        if result and result[-1].left_lineno is not None and result[-1].right_lineno is not None:
            if op.left_lineno is not None and op.right_lineno is not None:
                if op.left_lineno - result[-1].left_lineno >= 2 and op.right_lineno - result[-1].right_lineno >= 2:
                    result.append(_MergedDiffOpDots)
        result.append(op)

    # header and footer
    lines_a = a.splitlines(keepends=True)
    lines_b = b.splitlines(keepends=True)
    min_left_lineno = len(lines_a)
    max_left_lineno = -1
    min_right_lineno = len(lines_b)
    max_right_lineno = -1
    for op in ops:
        if op.left_lineno is not None:
            min_left_lineno = min(min_left_lineno, op.left_lineno)
            max_left_lineno = op.left_lineno
        if op.right_lineno is not None:
            min_right_lineno = min(min_right_lineno, op.right_lineno)
            max_right_lineno = op.right_lineno
    if min_left_lineno != 0 or min_right_lineno != 0:
        result = [_MergedDiffOpDots] + result
    if max_left_lineno != len(lines_a) - 1 or max_right_lineno != len(lines_b) - 1:
        result += [_MergedDiffOpDots]

    return result

def _summary_token_of_diff_ops(ops: List[_MergedDiffOp]) -> List[_PrettyToken]:
    removed = 0
    added = 0
    for op in ops:
        if op.has_diff:
            if op.left_lineno is not None:
                removed += 1
            if op.right_lineno is not None:
                added += 1
    if not removed and not added:
        return []
    else:
        return [_PrettyToken(_PrettyTokenType.HINT, '(also {} lines are deleted and {} lines are added...)'.format(removed, added))]

def check_lines_match(a: str, b: str, *, compare_mode: CompareMode) -> bool:
    if compare_mode == CompareMode.EXACT_MATCH:
        comparator: OutputComparator = ExactComparator()
    elif compare_mode == CompareMode.CRLF_INSENSITIVE_EXACT_MATCH:
        comparator = CRLFInsensitiveComparator(ExactComparator())
    elif compare_mode == CompareMode.IGNORE_SPACES:
        comparator = SplitComparator(ExactComparator())
    elif compare_mode == CompareMode.IGNORE_SPACES_AND_NEWLINES:
        raise RuntimeError('CompareMode.IGNORE_SPACES_AND_NEWLINES is not allowed for this function')
    else:
        assert False
    return comparator(a.encode(), b.encode())

def request(method: str, url: str, session: requests.Session, raise_for_status: bool = True, **kwargs) -> requests.Response:
    assert method in ['GET', 'POST']
    kwargs.setdefault('allow_redirects', True)
    logger.info('%s: %s', method, url)
    if 'data' in kwargs:
        logger.debug('data: %s', repr(kwargs['data']))
    resp = session.request(method, url, **kwargs)
    if resp.url != url:
        logger.info('redirected: %s', resp.url)
    logger.info(describe_status_code(resp.status_code))
    if raise_for_status:
        resp.raise_for_status()
    return resp

def new_session_with_our_user_agent(*, path: pathlib.Path) -> Iterator[requests.Session]:
    session = requests.Session()
    session.headers['User-Agent'] = '{}/{} (+{})'.format(version.__package_name__, version.__version__, version.__url__)
    logger.debug('User-Agent: %s', session.headers['User-Agent'])
    try:
        with utils.with_cookiejar(session, path=path) as session:
            yield session
    except http.cookiejar.LoadError:
        logger.info(HINT + 'You can delete the broken cookie.jar file: %s', str(path))
        raise

def get_latest_version_from_pypi(package_name: str) -> str:
    pypi_url = 'https://pypi.org/pypi/{}/json'.format(package_name)
    version_cache_path = user_cache_dir / "pypi.json"
    update_interval = 60 * 60 * 8  # 8 hours

    # load cache
    cache: Dict[str, Any] = {}
    if version_cache_path.exists():
        try:
            logger.debug('load the cache for update checking: %s', str(version_cache_path))
            with version_cache_path.open() as fh:
                cache = json.load(fh)
            if time.time() < cache[package_name]['time'] + update_interval:
                return cache[package_name]['version']
        except Exception as e:
            logger.warning('failed to load the cache in update checking: %s', e)

    # get
    try:
        resp = request('GET', pypi_url, session=requests.Session())
        data = json.loads(resp.content.decode())
        value = data['info']['version']
    except requests.RequestException as e:
        logger.error(str(e))
        value = '0.0.0'  # ignore since this failure is not important
    cache[package_name] = {
        'time': int(time.time()),  # use timestamp because Python's standard datetime library is too weak to parse strings
        'version': value,
    }

    # store cache
    logger.debug('store the cache for update checking: %s', str(version_cache_path))
    version_cache_path.parent.mkdir(parents=True, exist_ok=True)
    with version_cache_path.open('w') as fh:
        json.dump(cache, fh)

    return value

def run_for_package(*, package_name: str, current_version: str) -> bool:
    is_updated = not is_update_available_on_pypi(package_name, current_version)
    if not is_updated:
        logger.warning('update available for %s: %s -> %s', package_name, current_version, get_latest_version_from_pypi(package_name))
        logger.info('run: $ pip3 install -U %s', package_name)
    return is_updated

def __call__(self, actual: bytes, expected: bytes) -> bool:
    """
    :returns: True if the relative error or absolute error is smaller than the accepted error
    """
    try:
        x: Optional[float] = float(actual)
    except ValueError:
        x = None
    try:
        y: Optional[float] = float(expected)
    except ValueError:
        y = None
    if x is not None and y is not None:
        return math.isclose(x, y, rel_tol=self.rel_tol, abs_tol=self.abs_tol)
    else:
        return actual == expected

def build_match_function(*, compare_mode: CompareMode, error: Optional[float], judge_command: Optional[str], silent: bool, test_input_path: pathlib.Path, test_output_path: Optional[pathlib.Path]) -> Callable[[bytes, bytes], bool]:
    """build_match_function builds the function to compare actual outputs and expected outputs.

    This function doesn't any I/O.
    """

    if judge_command is not None:
        special_judge = SpecialJudge(judge_command=judge_command, is_silent=silent)

        def run_judge_command(actual: bytes, expected: bytes) -> bool:
            # the second argument is ignored
            return special_judge.run(
                actual_output=actual,
                input_path=test_input_path,
                expected_output_path=test_output_path,
            )

        return run_judge_command

    is_exact = False
    if compare_mode == CompareMode.EXACT_MATCH and error is None:
        is_exact = True
        file_comparator: output_comparators.OutputComparator = output_comparators.ExactComparator()
    elif compare_mode == CompareMode.CRLF_INSENSITIVE_EXACT_MATCH and error is None:
        is_exact = True
        file_comparator = output_comparators.CRLFInsensitiveComparator(output_comparators.ExactComparator())
    else:
        if error is not None:
            word_comparator: output_comparators.OutputComparator = output_comparators.FloatingPointNumberComparator(rel_tol=error, abs_tol=error)
        else:
            word_comparator = output_comparators.ExactComparator()
        if compare_mode in (CompareMode.EXACT_MATCH, CompareMode.CRLF_INSENSITIVE_EXACT_MATCH, CompareMode.IGNORE_SPACES):
            file_comparator = output_comparators.SplitLinesComparator(output_comparators.SplitComparator(word_comparator))
        elif compare_mode == CompareMode.IGNORE_SPACES_AND_NEWLINES:
            file_comparator = output_comparators.SplitComparator(word_comparator)
        else:
            assert False
        file_comparator = output_comparators.CRLFInsensitiveComparator(file_comparator)

    def compare_outputs(actual: bytes, expected: bytes) -> bool:
        result = file_comparator(actual, expected)
        if not result and is_exact:
            non_stcict_comparator = output_comparators.CRLFInsensitiveComparator(output_comparators.SplitComparator(output_comparators.ExactComparator()))
            if non_stcict_comparator(actual, expected):
                logger.warning('This was AC if spaces and newlines were ignored. Please use --ignore-spaces (-S) option or --ignore-spaces-and-newline (-N) option.')
        return result

    return compare_outputs

def run_checking_output(*, answer: bytes, test_output_path: Optional[pathlib.Path], is_special_judge: bool, match_function: Callable[[bytes, bytes], bool]) -> Optional[bool]:
    """run_checking_output executes matching of the actual output and the expected output.

    This function has file I/O including the execution of the judge command.
    """

    if test_output_path is None and not is_special_judge:
        return None
    if test_output_path is not None:
        with test_output_path.open('rb') as outf:
            expected = outf.read()
    else:
        # only if --judge option
        expected = b''
        logger.warning('expected output is not found')
    return match_function(answer, expected)

def display_result(proc: subprocess.Popen, answer: str, memory: Optional[float], test_input_path: pathlib.Path, test_output_path: Optional[pathlib.Path], *, mle: Optional[float], display_mode: DisplayMode, compare_mode: CompareMode, does_print_input: bool, silent: bool, match_result: Optional[bool]) -> JudgeStatus:
    """display_result prints the result of the test and its statistics.

    This function prints many logs and does some I/O.
    """

    # prepare the function to print the input
    is_input_printed = False

    def print_input() -> None:
        nonlocal is_input_printed
        if does_print_input and not is_input_printed:
            is_input_printed = True
            with test_input_path.open('rb') as inf:
                logger.info(utils.NO_HEADER + 'input:\n%s', pretty_printers.make_pretty_large_file_content(inf.read(), limit=40, head=20, tail=10))

    # check TLE, RE or not
    status = JudgeStatus.AC
    if proc.returncode is None:
        logger.info(utils.FAILURE + '' + utils.red('TLE'))
        status = JudgeStatus.TLE
        if not silent:
            print_input()
    elif memory is not None and mle is not None and memory > mle:
        logger.info(utils.FAILURE + '' + utils.red('MLE'))
        status = JudgeStatus.MLE
        if not silent:
            print_input()
    elif proc.returncode != 0:
        logger.info(utils.FAILURE + '' + utils.red('RE') + ': return code %d', proc.returncode)
        status = JudgeStatus.RE
        if not silent:
            print_input()

    # check WA or not
    if match_result is not None and not match_result:
        if status == JudgeStatus.AC:
            logger.info(utils.FAILURE + '' + utils.red('WA'))
        status = JudgeStatus.WA
        if not silent:
            print_input()
            if test_output_path is not None:
                with test_output_path.open('rb') as outf:
                    expected = outf.read().decode()
            else:
                expected = ''
            if display_mode == DisplayMode.SUMMARY:
                logger.info(utils.NO_HEADER + 'output:\n%s', pretty_printers.make_pretty_large_file_content(answer.encode(), limit=40, head=20, tail=10))
                logger.info(utils.NO_HEADER + 'expected:\n%s', pretty_printers.make_pretty_large_file_content(expected.encode(), limit=40, head=20, tail=10))
            elif display_mode == DisplayMode.ALL:
                logger.info(utils.NO_HEADER + 'output:\n%s', pretty_printers.make_pretty_all(answer.encode()))
                logger.info(utils.NO_HEADER + 'expected:\n%s', pretty_printers.make_pretty_all(expected.encode()))
            elif display_mode == DisplayMode.DIFF:
                logger.info(utils.NO_HEADER + pretty_printers.make_pretty_diff(answer.encode(), expected=expected, compare_mode=compare_mode, limit=40))
            elif display_mode == DisplayMode.DIFF_ALL:
                logger.info(utils.NO_HEADER + pretty_printers.make_pretty_diff(answer.encode(), expected=expected, compare_mode=compare_mode, limit=-1))
            else:
                assert False
    if match_result is None:
        if not silent:
            print_input()
            logger.info(utils.NO_HEADER + 'output:\n%s', pretty_printers.make_pretty_large_file_content(answer.encode(), limit=40, head=20, tail=10))
    if status == JudgeStatus.AC:
        logger.info(utils.SUCCESS + '' + utils.green('AC'))

    return status

def check_gnu_time(gnu_time: str) -> bool:
    try:
        with tempfile.NamedTemporaryFile(delete=True) as fh:
            subprocess.check_call([gnu_time, '-f', '%M KB', '-o', fh.name, '--', 'true'])
            with open(fh.name) as fh1:
                data = fh1.read()
            int(utils.remove_suffix(data.rstrip().splitlines()[-1], ' KB'))
            return True
    except NameError:
        raise  # NameError is not a runtime error caused by the environment, but a coding mistake
    except AttributeError:
        raise  # AttributeError is also a mistake
    except Exception:
        logger.debug(traceback.format_exc())
    return False

def run(args: 'argparse.Namespace') -> int:
    # list tests
    if not args.test:
        args.test = fmtutils.glob_with_format(args.directory, args.format)  # by default
    if args.ignore_backup:
        args.test = fmtutils.drop_backup_or_hidden_files(args.test)
    tests = fmtutils.construct_relationship_of_files(args.test, args.directory, args.format)

    # check wheather GNU time is available
    if args.gnu_time is None:
        if platform.system() == 'Darwin':
            args.gnu_time = 'gtime'
        else:
            args.gnu_time = 'time'
    if not check_gnu_time(args.gnu_time):
        logger.warning('GNU time is not available: %s', args.gnu_time)
        if platform.system() == 'Darwin':
            logger.info(utils.HINT + 'You can install GNU time with: $ brew install gnu-time')
        args.gnu_time = None
    if args.mle is not None and args.gnu_time is None:
        raise RuntimeError('--mle is used but GNU time does not exist')

    # run tests
    history: List[Dict[str, Any]] = []
    if args.jobs is None:
        for name, paths in sorted(tests.items()):
            history += [test_single_case(name, paths['in'], paths.get('out'), args=args)]
    else:
        if os.name == 'nt':
            logger.warning("-j/--jobs opiton is unstable on Windows environmet")
        with concurrent.futures.ThreadPoolExecutor(max_workers=args.jobs) as executor:
            lock = threading.Lock()
            futures: List[concurrent.futures.Future] = []
            for name, paths in sorted(tests.items()):
                futures += [executor.submit(test_single_case, name, paths['in'], paths.get('out'), lock=lock, args=args)]
            for future in futures:
                history += [future.result()]

    # summarize
    slowest: float = -1.0
    slowest_name = ''
    heaviest: float = -1.0
    heaviest_name = ''
    ac_count = 0
    for result in history:
        if result['status'] == 'AC':
            ac_count += 1
        if slowest < result['elapsed']:
            slowest = result['elapsed']
            slowest_name = result['testcase']['name']
        if result['memory'] is not None and heaviest < result['memory']:
            heaviest = result['memory']
            heaviest_name = result['testcase']['name']

    # print the summary
    logger.info('')
    logger.info('slowest: %f sec  (for %s)', slowest, slowest_name)
    if heaviest >= 0:
        if heaviest < MEMORY_WARNING:
            logger.info('max memory: %f MB  (for %s)', heaviest, heaviest_name)
        else:
            logger.warning('max memory: %f MB  (for %s)', heaviest, heaviest_name)
    if ac_count == len(tests):
        logger.info(utils.SUCCESS + 'test ' + utils.green('success') + ': %d cases', len(tests))
    else:
        logger.info(utils.FAILURE + 'test ' + utils.red('failed') + ': %d AC / %d cases', ac_count, len(tests))

    if args.log_file:
        with args.log_file.open(mode='w') as fh:
            json.dump(history, fh)

    # return the result
    return ac_count == len(tests)

def compare_outputs(actual: bytes, expected: bytes) -> bool:
    result = file_comparator(actual, expected)
    if not result and is_exact:
        non_stcict_comparator = output_comparators.CRLFInsensitiveComparator(output_comparators.SplitComparator(output_comparators.ExactComparator()))
        if non_stcict_comparator(actual, expected):
            logger.warning('This was AC if spaces and newlines were ignored. Please use --ignore-spaces (-S) option or --ignore-spaces-and-newline (-N) option.')
    return result

def print_input() -> None:
    nonlocal is_input_printed
    if does_print_input and not is_input_printed:
        is_input_printed = True
        with test_input_path.open('rb') as inf:
            logger.info(utils.NO_HEADER + 'input:\n%s', pretty_printers.make_pretty_large_file_content(inf.read(), limit=40, head=20, tail=10))

def __call__(self, actual: bytes, expected: bytes) -> bool:
    # str.split() also removes trailing '\r'
    actual_words = actual.split()
    expected_words = expected.split()
    if len(actual_words) != len(expected_words):
        return False
    for x, y in zip(actual_words, expected_words):
        if not self.word_comparator(x, y):
            return False
    return True

def __call__(self, actual: bytes, expected: bytes) -> bool:
    actual_lines = actual.rstrip(b'\n').split(b'\n')
    expected_lines = expected.rstrip(b'\n').split(b'\n')
    if len(actual_lines) != len(expected_lines):
        return False
    for x, y in zip(actual_lines, expected_lines):
        if not self.line_comparator(x, y):
            return False
    return True

def simple_match(a: str, b: str) -> bool:
    if a == b:
        return True
    if a.rstrip() == b.rstrip():
        logger.warning('WA if no rstrip')
        return True
    return False

def percentsplit(s: str) -> Generator[str, None, None]:
    for m in re.finditer('[^%]|%(.)', s):
        yield m.group(0)

def percentformat(s: str, table: Dict[str, str]) -> str:
    assert '%' not in table or table['%'] == '%'
    table['%'] = '%'
    result = ''
    for c in percentsplit(s):
        if c.startswith('%'):
            result += table[c[1]]
        else:
            result += c
    return result

def glob_with_format(directory: pathlib.Path, format: str) -> List[pathlib.Path]:
    if os.name == 'nt':
        format = format.replace('/', '\\')
    table = {}
    table['s'] = '*'
    table['e'] = '*'
    pattern = (glob.escape(str(directory) + os.path.sep) + percentformat(glob.escape(format).replace(glob.escape('%'), '%'), table))
    paths = list(map(pathlib.Path, glob.glob(pattern)))
    for path in paths:
        logger.debug('testcase globbed: %s', path)
    return paths

def match_with_format(directory: pathlib.Path, format: str, path: pathlib.Path) -> Optional[Match[str]]:
    if os.name == 'nt':
        format = format.replace('/', '\\')
    table = {}
    table['s'] = '(?P<name>.+)'
    table['e'] = '(?P<ext>in|out)'
    pattern = re.compile(re.escape(str(directory.resolve()) + os.path.sep) + percentformat(re.escape(format).replace(re.escape('%'), '%'), table))
    return pattern.match(str(path.resolve()))

def path_from_format(directory: pathlib.Path, format: str, name: str, ext: str) -> pathlib.Path:
    table = {}
    table['s'] = name
    table['e'] = ext
    return directory / percentformat(format, table)

def percentparse(s: str, format: str, table: Dict[str, str]) -> Optional[Dict[str, str]]:
    table = {key: '(?P<{}>{})'.format(key, value) for key, value in table.items()}
    used: Set[str] = set()
    pattern = ''
    for token in percentsplit(re.escape(format).replace('\\%', '%')):
        if token.startswith('%'):
            c = token[1]
            if c not in used:
                pattern += table[c]
                used.add(c)
            else:
                pattern += r'(?P={})'.format(c)
        else:
            pattern += token
    m = re.match(pattern, s)
    if not m:
        return None
    return m.groupdict()

def add(self, problem: Problem, *, directory: pathlib.Path) -> None:
    logger.info('append the downloading history: %s', self.path)
    self.path.parent.mkdir(parents=True, exist_ok=True)
    with open(self.path, 'a') as fh:
        fh.write(json.dumps({
            'timestamp': int(time.time()),  # this should not be int, but Python's strptime is too weak and datetime.fromisoformat is from 3.7
            'directory': str(directory),
            'url': problem.get_url(),
        }) + '\n')
    self._flush()

def is_backup_or_hidden_file(path: pathlib.Path) -> bool:
    basename = path.name
    return basename.endswith('~') or (basename.startswith('#') and basename.endswith('#')) or basename.startswith('.')

def drop_backup_or_hidden_files(paths: List[pathlib.Path]) -> List[pathlib.Path]:
    result: List[pathlib.Path] = []
    for path in paths:
        if is_backup_or_hidden_file(path):
            logger.warning('ignore a backup file: %s', path)
        else:
            result += [path]
    return result

def get(self, *, directory: pathlib.Path) -> List[str]:
    if not self.path.exists():
        return []

    logger.info('read history from: %s', self.path)
    found = set()
    with open(self.path) as fh:
        for line in fh:
            try:
                data = json.loads(line)
            except json.decoder.JSONDecodeError:
                logger.warning('corrupted line found in: %s', self.path)
                logger.debug('%s', traceback.format_exc())
                continue
            if pathlib.Path(data['directory']) == directory:
                found.add(data['url'])
    logger.info('found urls in history:\n%s', '\n'.join(found))
    return list(found)

def run(args: argparse.Namespace) -> bool:
    """
    :returns: whether the submission is succeeded or not.
    """

    # guess url
    history = onlinejudge_command.download_history.DownloadHistory()
    if args.file.parent.resolve() == pathlib.Path.cwd():
        guessed_urls = history.get(directory=pathlib.Path.cwd())
    else:
        logger.warning('cannot guess URL since the given file is not in the current directory')
        guessed_urls = []
    if args.url is None:
        if len(guessed_urls) == 1:
            args.url = guessed_urls[0]
            logger.info('guessed problem: %s', args.url)
        else:
            logger.error('failed to guess the URL to submit')
            logger.info('please manually specify URL as: $ oj submit URL FILE')
            return False

    # parse url
    problem = dispatch.problem_from_url(args.url)
    if problem is None:
        return False

    # read code
    with args.file.open('rb') as fh:
        code: bytes = fh.read()

    # report code
    logger.info('code (%d byte):', len(code))
    logger.info(utils.NO_HEADER + '%s', pretty_printers.make_pretty_large_file_content(code, limit=30, head=10, tail=10))

    with utils.new_session_with_our_user_agent(path=args.cookie) as sess:
        # check the login status
        try:
            is_logged_in = problem.get_service().is_logged_in(session=sess)
        except Exception as e:
            logger.exception('failed to check the login status: %s', e)
            return False
        else:
            if is_logged_in:
                logger.info('You are logged in.')
            else:
                logger.error('You are not logged in. Please run $ oj login %s', problem.get_url())
                return False

        # guess or select language ids
        language_dict: Dict[LanguageId, str] = {language.id: language.name for language in problem.get_available_languages(session=sess)}
        matched_lang_ids: Optional[List[str]] = None
        if args.language in language_dict:
            matched_lang_ids = [args.language]
        else:
            if args.guess:
                kwargs = {
                    'language_dict': language_dict,
                    'cxx_latest': args.guess_cxx_latest,
                    'cxx_compiler': args.guess_cxx_compiler,
                    'python_version': args.guess_python_version,
                    'python_interpreter': args.guess_python_interpreter,
                }
                matched_lang_ids = guess_lang_ids_of_file(args.file, code, **kwargs)
                if not matched_lang_ids:
                    logger.info('failed to guess languages from the file name')
                    matched_lang_ids = list(language_dict.keys())
                if args.language is not None:
                    logger.info('you can use `--no-guess` option if you want to do an unusual submission')
                    matched_lang_ids = select_ids_of_matched_languages(args.language.split(), matched_lang_ids, language_dict=language_dict)
            else:
                if args.language is None:
                    matched_lang_ids = None
                else:
                    matched_lang_ids = select_ids_of_matched_languages(args.language.split(), list(language_dict.keys()), language_dict=language_dict)

        # report selected language ids
        if matched_lang_ids is not None and len(matched_lang_ids) == 1:
            args.language = matched_lang_ids[0]
            logger.info('chosen language: %s (%s)', args.language, language_dict[LanguageId(args.language)])
        else:
            if matched_lang_ids is None:
                logger.error('language is unknown')
                logger.info('supported languages are:')
            elif len(matched_lang_ids) == 0:
                logger.error('no languages are matched')
                logger.info('supported languages are:')
            else:
                logger.error('Matched languages were not narrowed down to one.')
                logger.info('You have to choose:')
            for lang_id in sorted(matched_lang_ids or language_dict.keys()):
                logger.info(utils.NO_HEADER + '%s (%s)', lang_id, language_dict[LanguageId(lang_id)])
            return False

        # confirm
        guessed_unmatch = ([problem.get_url()] != guessed_urls)
        if guessed_unmatch:
            samples_text = ('samples of "{}'.format('", "'.join(guessed_urls)) if guessed_urls else 'no samples')
            logger.warning('the problem "%s" is specified to submit, but %s were downloaded in this directory. this may be mis-operation', problem.get_url(), samples_text)
        if args.wait:
            time.sleep(args.wait / 2)
        if not args.yes:
            if guessed_unmatch:
                problem_id = problem.get_url().rstrip('/').split('/')[-1].split('?')[-1]  # this is too ad-hoc
                key = problem_id[:3] + (problem_id[-1] if len(problem_id) >= 4 else '')
                sys.stdout.write('Are you sure? Please type "{}" '.format(key))
                sys.stdout.flush()
                c = sys.stdin.readline().rstrip()
                if c != key:
                    logger.info('terminated.')
                    return False
            else:
                sys.stdout.write('Are you sure? [y/N] ')
                sys.stdout.flush()
                c = sys.stdin.read(1)
                if c.lower() != 'y':
                    logger.info('terminated.')
                    return False
        if args.wait:
            time.sleep(args.wait / 2)

        # submit
        try:
            submission = problem.submit_code(code, language_id=LanguageId(args.language), session=sess)
        except NotLoggedInError:
            logger.info(utils.FAILURE + 'login required')
            return False
        except SubmissionError:
            logger.info(utils.FAILURE + 'submission failed')
            return False

        # show result
        if args.open:
            utils.webbrowser_register_explorer_exe()
            try:
                browser = webbrowser.get()
            except webbrowser.Error as e:
                logger.error('%s', e)
                logger.info('please set the $BROWSER envvar')
            else:
                logger.info('open the submission page with browser: %s', browser)
                browser.open_new_tab(submission.get_url())

    return True

def select_ids_of_matched_languages(words: List[str], lang_ids: List[str], language_dict, split: bool = False, remove: bool = False) -> List[str]:
    result = []
    for lang_id in lang_ids:
        desc = language_dict[lang_id].lower()
        if split:
            desc = desc.split()
        pred = all(word.lower() in desc for word in words)
        if remove:
            pred = not pred
        if pred:
            result.append(lang_id)
    return result

def parse_python_version(description: str) -> Optional[int]:
    """
    :param description: must be for Python
    """

    assert is_python_description(description)
    match = re.match(r'([23])\.(?:\d+(?:\.\d+)?|x)', description)
    if match:
        return int(match.group(1))
    match = re.match(r'(?:Python|PyPy) *\(?([23])', description, re.IGNORECASE)
    if match:
        return int(match.group(1))
    return None

def parse_python_interpreter(description: str) -> str:
    """
    :param description: must be for Python
    """

    assert is_python_description(description)
    if 'pypy' in description.lower():
        return 'pypy'
    else:
        return 'cpython'

def textfile(s: str) -> str:  # should have trailing newline
    if s.endswith('\n'):
        return s
    elif '\r\n' in s:
        return s + '\r\n'
    else:
        return s + '\n'

def remove_suffix(s: str, suffix: str) -> str:
    assert s.endswith(suffix)
    return s[:-len(suffix)]

def exec_command(command_str: str, *, stdin: Optional[BinaryIO] = None, input: Optional[bytes] = None, timeout: Optional[float] = None, gnu_time: Optional[str] = None) -> Tuple[Dict[str, Any], subprocess.Popen]:
    if input is not None:
        assert stdin is None
        stdin = subprocess.PIPE  # type: ignore
    if gnu_time is not None:
        context: Any = tempfile.NamedTemporaryFile(delete=True)
    else:
        context = contextlib.ExitStack()  # TODO: we should use contextlib.nullcontext() if possible
    with context as fh:
        command = shlex.split(command_str)
        if gnu_time is not None:
            command = [gnu_time, '-f', '%M', '-o', fh.name, '--'] + command
        if os.name == 'nt':
            # HACK: without this encoding and decoding, something randomly fails with multithreading; see https://github.com/kmyk/online-judge-tools/issues/468
            command = command_str.encode().decode()  # type: ignore
        begin = time.perf_counter()

        # We need kill processes called from the "time" command using process groups. Without this, orphans spawn. see https://github.com/kmyk/online-judge-tools/issues/640
        preexec_fn = None
        if gnu_time is not None and os.name == 'posix':
            preexec_fn = os.setsid

        try:
            proc = subprocess.Popen(command, stdin=stdin, stdout=subprocess.PIPE, stderr=sys.stderr, preexec_fn=preexec_fn)  # pylint: disable=subprocess-popen-preexec-fn
        except FileNotFoundError:
            logger.error('No such file or directory: %s', command)
            sys.exit(1)
        except PermissionError:
            logger.error('Permission denied: %s', command)
            sys.exit(1)
        answer: Optional[bytes] = None
        try:
            answer, _ = proc.communicate(input=input, timeout=timeout)
        except subprocess.TimeoutExpired:
            pass
        finally:
            if preexec_fn is not None:
                try:
                    os.killpg(os.getpgid(proc.pid), signal.SIGTERM)
                except ProcessLookupError:
                    pass
            else:
                proc.terminate()

        end = time.perf_counter()
        memory: Optional[float] = None
        if gnu_time is not None:
            with open(fh.name) as fh1:
                reported = fh1.read()
            logger.debug('GNU time says:\n%s', reported)
            if reported.strip() and reported.splitlines()[-1].isdigit():
                memory = int(reported.splitlines()[-1]) / 1000
    info = {
        'answer': answer,  # Optional[byte]
        'elapsed': end - begin,  # float, in second
        'memory': memory,  # Optional[float], in megabyte
    }
    return info, proc

def generate_output_single_case_exists_ok(test_name: str, test_input_path: pathlib.Path, test_output_path: Optional[pathlib.Path], *, lock: Optional[threading.Lock] = None, args: argparse.Namespace) -> None:
    if test_output_path is not None:
        nullcontext = contextlib.ExitStack()
        with lock or nullcontext:
            logger.info('')
            logger.info('%s', test_name)
            logger.info('output file already exists.')
            logger.info('skipped.')
    else:
        generate_output_single_case(test_name, test_input_path, lock=lock, args=args)

def webbrowser_register_explorer_exe() -> None:
    """webbrowser_register_explorer registers `explorer.exe` in the list of browsers under Windows Subsystem for Linux.

    See https://github.com/online-judge-tools/oj/issues/773
    """

    # There is an issue that the terminal is cleared after `.open_new_tab()`. The reason is unknown, but adding an argurment `preferred=True` to `webbrowser.register` resolves this issues.

    # See https://github.com/online-judge-tools/oj/pull/784

    if not is_windows_subsystem_for_linux():
        return
    instance = webbrowser.GenericBrowser('explorer.exe')
    if sys.version_info < (3, 7):
        webbrowser.register('explorer', None, instance)  # TODO: remove this after Python 3.6 supprot is finished
    else:
        webbrowser.register('explorer', None, instance, preferred=True)  # `preferred=True` solves the issue that terminal logs are cleared on cmd.exe with stopping using wslview via www-browser. TODO: remove `preferred=True` after https://github.com/wslutilities/wslu/issues/199 is fixed.

def is_cplusplus_description(description: str) -> bool:
    # Here, 'clang' is not used as intended. Think about strings like "C++ (Clang)", "Clang++" (this includes "g++" as a substring), or "C (Clang)".
    return 'c++' in description.lower() or 'g++' in description.lower()

def parse_cplusplus_compiler(description: str) -> str:
    """
    :param description: must be for C++
    """

    assert is_cplusplus_description(description)
    if 'clang' in description.lower():
        return 'clang'
    if 'gcc' in description.lower() or 'g++' in description.lower():
        return 'gcc'
    return 'gcc'  # by default

def parse_cplusplus_version(description: str) -> Optional[str]:
    """
    :param description: must be for C++
    """

    assert is_cplusplus_description(description)
    match = re.search(r'[CG]\+\+\s?(\d\w)\b', description)
    if match:
        return match.group(1)
    return None

def login_with_password(service: Service, *, username: Optional[str], password: Optional[str], session: requests.Session) -> None:
    def get_credentials() -> Tuple[str, str]:
        nonlocal username, password
        if username is None:
            username = input('Username: ')
        if password is None:
            password = getpass.getpass()
        return username, password

    service.login(get_credentials=get_credentials, session=session)

def get_webdriver() -> Any:
    """get_webdriver() detects an available webdriver and returns it.

    :raises ImportError: of Selenium
    """

    import selenium.webdriver  # pylint: disable=import-error,import-outside-toplevel

    logger.info('Trying to open Chrome via WebDriver...')
    try:
        return selenium.webdriver.Chrome()
    except selenium.common.exceptions.WebDriverException as e:
        logger.error(e)

    logger.info('Trying to open Firefox via WebDriver...')
    try:
        return selenium.webdriver.Firefox()
    except Exception as e:
        logger.error(e)

    logger.info('Trying to open Edge via WebDriver...')
    try:
        return selenium.webdriver.Edge()
    except Exception as e:
        logger.error(e)

    logger.info('Trying to open Internet Explorer via WebDriver...')
    try:
        return selenium.webdriver.Ie()
    except Exception as e:
        logger.error(e)

    logger.info('Trying to open Safari via WebDriver...')
    try:
        return selenium.webdriver.Safari()
    except Exception as e:
        logger.error(e)

    logger.info('Trying to open Opera via WebDriver...')
    try:
        return selenium.webdriver.Opera()
    except Exception as e:
        logger.error(e)

    logger.error('No WebDriver is available.')
    logger.info(utils.HINT + textwrap.dedent("""
        Please install a WebDriver.
        See https://www.selenium.dev/documentation/en/webdriver/driver_requirements/

        Detailed instructions:
            If you use Ubuntu:
                1. Run $ sudo apt install chromium-chromedriver firefox-geckodriver
            If you use Ubuntu under Windows Subsystem for Linux:
                1. Make a symbolic link from cookie.jar in WSL to cookie.jar out of WSL. For example, run $ ln -s /mnt/c/Users/%USERNAME%/AppData/Local/online-judge-tools/online-judge-tools/cookie.jar /home/ubuntu/.local/share/online-judge-tools/cookie.jar
                2. Use `oj login` outside of WSL
            If you use Windows:
                1. Install Chocolatey. See https://chocolatey.org/
                2. Run > choco install selenium-all-drivers
    """))
    raise WebDriverException('No WebDriver is installed.')

def is_logged_in_with_message(service: Service, *, session: requests.Session) -> bool:
    if service.is_logged_in(session=session):
        logger.info(utils.SUCCESS + 'You have already signed in.')
        return True
    else:
        logger.info(utils.FAILURE + 'You are not signed in.')
        return False

def run(args: argparse.Namespace) -> bool:
    """
    :returns: whether it is logged in or not.
    """

    service = dispatch.service_from_url(args.url)
    if service is None:
        return False

    with utils.new_session_with_our_user_agent(path=args.cookie) as session:

        if is_logged_in_with_message(service, session=session):
            return True
        else:
            if args.check:
                return False

        if args.use_browser in ('always', 'auto'):
            try:
                login_with_browser(service, session=session)
            except ImportError:
                logger.error('Selenium is not installed. Please run $ pip3 install selenium')
            except WebDriverException as e:
                logger.debug(e)
            else:
                return is_logged_in_with_message(service, session=session)

        if args.use_browser in ('never', 'auto'):
            if args.use_browser == 'auto':
                logger.warning('Switch to use CUI-based login instead of Selenium')
            try:
                login_with_password(service, username=args.username, password=args.password, session=session)
            except NotImplementedError as e:
                logger.exception(e)
            except LoginError as e:
                logger.debug(e)
            except Exception as e:
                logger.exception(e)
            else:
                return is_logged_in_with_message(service, session=session)

        return False

